@Test
public void testRmtDataCache() {
    FlowCtrlRuleHandler groupFlowCtrlRuleHandler = new FlowCtrlRuleHandler(false);
    FlowCtrlRuleHandler defFlowCtrlRuleHandler = new FlowCtrlRuleHandler(true);
    List<Partition> partitions = new ArrayList<>();
    BrokerInfo brokerInfo = new BrokerInfo(1, "127.0.0.1", 18080);
    Partition expectPartition = new Partition(brokerInfo, "test", 1);
    partitions.add(expectPartition);
    RmtDataCache cache = new RmtDataCache(defFlowCtrlRuleHandler, groupFlowCtrlRuleHandler, partitions);
    List<Partition> brokerPartitions = cache.getBrokerPartitionList(brokerInfo);
    assertEquals(1, brokerPartitions.size());
    assertEquals(expectPartition.getPartitionId(), brokerPartitions.get(0).getPartitionId());
    ConcurrentLinkedQueue<Partition> partitionQueue = cache.getPartitionByBroker(brokerInfo);
    assertEquals(1, partitionQueue.size());
    assertEquals(expectPartition.getPartitionId(), partitionQueue.peek().getPartitionId());
    Set<BrokerInfo> brokerInfos = cache.getAllRegisterBrokers();
    assertEquals(1, brokerInfos.size());
    assertTrue(brokerInfos.contains(brokerInfo));
    assertEquals(expectPartition.getPartitionId(), cache.getPartitionByKey("1:test:1").getBrokerId());
    cache.addPartition(new Partition(brokerInfo, "test", 2), 10, 20);
    assertEquals(2, cache.getBrokerPartitionList(brokerInfo).size());
    assertTrue(cache.isPartitionsReady(1000));
    cache.pullSelect();
    cache.pushSelect();
    cache.removePartition(expectPartition);
    assertEquals(1, cache.getBrokerPartitionList(brokerInfo).size());
    assertEquals(1, cache.getCurPartitionInfoMap().size());
    assertEquals(1, cache.getAllPartitionListWithStatus().size());
    cache.resumeTimeoutConsumePartitions(true, 1000);
    Map<BrokerInfo, List<Partition>> infoMap = new HashMap<>();
    cache.removeAndGetPartition(infoMap, new ArrayList<String>(), 1000, true);
    cache.getSubscribeInfoList("test", "test");
    cache.errReqRelease("1:test:2", 1000, true);
    cache.succRspRelease("1:test:2", "test", 1000, true, true, 1000, 2000);
    cache.close();
}

@Test
public void testTubeBaseSessionFactory() throws Exception {
    TubeClientConfig config = mock(TubeClientConfig.class);
    when(config.getMasterInfo()).thenReturn(new MasterInfo("192.168.1.1:18080"));
    ClientFactory clientFactory = mock(ClientFactory.class);
    PowerMockito.mockStatic(AddressUtils.class);
    PowerMockito.when(AddressUtils.getLocalAddress()).thenReturn("127.0.0.1:18080");
    TubeBaseSessionFactory factory = new TubeBaseSessionFactory(clientFactory, config);
    assertFalse(factory.isShutdown());
    // Use reflection to change the producer manager to a mock one
    ProducerManager mockPM = mock(ProducerManager.class);
    Field field = factory.getClass().getDeclaredField("producerManager");
    field.setAccessible(true);
    field.set(factory, mockPM);
    MessageProducer producer = factory.createProducer();
    assertEquals(1, factory.getCurrClients().size());
    final PullMessageConsumer pullMessageConsumer = factory.createPullConsumer(new ConsumerConfig("192.168.1.1:18080", "test"));
    final PushMessageConsumer pushMessageConsumer = factory.createPushConsumer(new ConsumerConfig("192.168.1.1:18080", "test"));
    assertEquals(3, factory.getCurrClients().size());
    factory.removeClient(producer);
    factory.removeClient(pullMessageConsumer);
    factory.removeClient(pushMessageConsumer);
    assertEquals(0, factory.getCurrClients().size());
    factory.shutdown();
    assertTrue(factory.isShutdown());
}

